package com.lasheel.smartpantry;
import android.app.*;import android.os.*;import android.database.*;import android.widget.*;
public class EditActivity extends Activity {DB db;int id;public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);id=getIntent().getIntExtra("id",-1);String name="",qty="",unit="piece",expiry="";if(id>=0)try(Cursor c=db.item(id)){if(c.moveToFirst()){name=c.getString(1);qty=""+c.getDouble(2);unit=c.getString(3);expiry=c.getString(4);}}LinearLayout l=UI.page(this,id<0?"Add Ingredient":"Edit Ingredient");EditText n=UI.input(this,l,"Ingredient name",name),q=UI.input(this,l,"Quantity (positive number)",qty),u=UI.input(this,l,"Unit: g, kg, ml, l, piece, slice",unit),e=UI.input(this,l,"Expiry (optional YYYY-MM-DD)",expiry==null?"":expiry);q.setInputType(8194);UI.button(this,l,"Save",()->{String nm=n.getText().toString().trim(),un=u.getText().toString().trim().toLowerCase(),ex=e.getText().toString().trim();double v;try{v=Double.parseDouble(q.getText().toString());}catch(Exception err){UI.msg(this,"Enter a valid quantity");return;}if(nm.isEmpty()||v<=0||!(un.equals("g")||un.equals("kg")||un.equals("ml")||un.equals("l")||un.equals("piece")||un.equals("pieces")||un.equals("slice")||un.equals("slices"))){UI.msg(this,"Enter a name, positive quantity and supported unit");return;}if(!ex.isEmpty()&&!ex.matches("\\d{4}-\\d{2}-\\d{2}")){UI.msg(this,"Use YYYY-MM-DD for expiry");return;}db.save(id,nm,v,un,ex);finish();});if(id>=0)UI.button(this,l,"Delete ingredient",()->new AlertDialog.Builder(this).setMessage("Delete this ingredient?").setPositiveButton("Delete",(d,w)->{db.delete(id);finish();}).setNegativeButton("Cancel",null).show());}}